INSERT INTO chapters (id, title_zh, description_zh, sort_order, released) VALUES
  ('simple', '简单句', '五大句型主干。', 1, true),
  ('predicate', '谓语', '时态、语态、情态。', 2, true),
  ('nonfinite', '非谓语', '不定式、分词、动名词。', 3, true);
INSERT INTO grammar_points (id, title_zh, body_zh) VALUES
  ('gp-s', '主语 S', '动作的发出者。可以是 He / She / I / They 等人称。'),
  ('gp-v', '谓语 V', '句子的核心动词。时态、语态都体现在这里。'),
  ('gp-past-sent', '过去式 sent', 'sent 是 send 的过去式，表示已经发生的动作。'),
  ('gp-past-made', '过去式 made', 'made 是 make 的过去式，表示已经发生的动作。'),
  ('gp-io', '间接宾语 IO', '给谁。一般是人，紧跟动词：me / him / her / us。'),
  ('gp-do', '直接宾语 DO', '给什么。一般是物：a book / an email / a cake。'),
  ('gp-o', '宾语 O', '动作承受的对象：music / books / lunch。'),
  ('gp-ditrans', '主谓双宾 S+V+IO+DO', '及物动词后接两个宾语：间接宾语（给谁）+ 直接宾语（给什么）。常见 send / give / show。'),
  ('gp-svo', '主谓宾 S+V+O', '及物动词后直接跟宾语，没有间接宾语。主语 + 谓语 + 宾语。'),
  ('gp-sv', '主谓 S+V', '不及物动词作谓语，后面不接宾语。主语 + 谓语即可成句。'),
  ('gp-modal', '情态动词', 'must / can / will 等表达语气。动词不一定都是谓语，情态动词不能单独作谓语。'),
  ('gp-modal-not-alone', '情态动词不能单独作谓语', 'must 后面还要接动词。只说 She must，句子不完整。'),
  ('gp-modal-predicate', '情态+原形构成谓语', 'must be 一起才是谓语。情态动词后接 be 或实义动词原形，共同构成谓语。'),
  ('gp-c', '表语 C', '系动词 be 后面的形容词或名词，说明主语状态：very beautiful / very tired。'),
  ('gp-link', '系动词', 'be（is / am / are）连接主语和表语，说明主语是什么或怎么样。'),
  ('gp-spc', '主系表 S+V+C', '主语 + 系动词 + 表语。表语是形容词或名词，说明主语状态。'),
  ('gp-oc', '宾语补足语 OC', '及物动词（make / find / call）后，补充说明宾语：happy / sad / Tom。'),
  ('gp-svoc', '主谓宾补 S+V+O+OC', '主语 + 谓语 + 宾语 + 宾补。宾补说明宾语变成什么或处于什么状态。'),
  ('gp-predicate-form', '谓语动词的形式', '实义动词和系动词作谓语时都要变形：配合主语的人称和数、体现时态和语态。祈使句是例外，直接用动词原形。'),
  ('gp-v-agree', '动词配合主语', '谓语动词形式随主语的人称和数变化：第三人称单数主语用 plays / is，其他主语用 play / are。'),
  ('gp-be-forms', 'be 的变形', 'be 作系动词或助动词时变形最多：am / is / are / was / were，随主语人称、数和时态变化。'),
  ('gp-imperative', '祈使句用原形', '祈使句省去主语，直接用动词原形开头：Open the door. Sit down.'),
  ('gp-nonfinite-forms', '非谓语三种形态', 'to do 多表目的、将来；doing 多表主动、进行；done 多表被动、完成。形态选择看与主句主语的关系。'),
  ('gp-inf-to-do', '不定式 to do', '多表目的和将来：I came to help you.（为了帮你）'),
  ('gp-ing-form', '现在分词 doing', '多表主动和进行：The boy running over there is Tom.（跑着的那个男孩）'),
  ('gp-past-part', '过去分词 done', '多表被动和完成：The window broken by the ball is mine.（被球打破的窗户）'),
  ('gp-nonfinite-subject', '非谓语作主语', '动词原形不能直接作主语、宾语；要充当这些成分必须变为非谓语：doing（动名词）或 to do（不定式）。'),
  ('gp-gerund-subject', '动名词作主语', 'doing 作主语，表示习惯性、一般性的动作：Surfing the internet is my favorite.'),
  ('gp-inf-subject', '不定式作主语', 'to do 作主语，常表具体的、将来的动作：To help others is my goal.'),
  ('gp-inf-recognition', '用 to 识别非谓语', '判断动词是谓语还是非谓语，看它前面有没有 to：to + 动词原形一定是非谓语（不定式）。'),
  ('gp-participle-adverbial', '分词作状语', '完整分句可降级为状语：谓语变 doing、删掉分句主语（分句主语需与主句主语一致）。Seeing his mother, the kid cried. = the kid saw his mother.'),
  ('gp-gerund-vs-participle', '动名词 vs 现在分词', 'doing 作名词性成分（主语/宾语/表语）叫动名词；作修饰性成分（定语/状语/宾补）叫现在分词。形式相同，身份看句法位置。'),
  ('gp-nonfinite-tense', '非谓语不带时态', '分词本身不带时态，时态由主句谓语体现：She pushed the door, seeing... 中 pushed 表过去，seeing 仍是 doing 形式。'),
  ('gp-pp-active', '现在分词表主动', '主动关系用 doing：seeing / sitting 表示动作由其逻辑主语发出，不随主句时态变化。'),
  ('gp-pp-passive', '过去分词表被动', '被动关系用 done：The sports meeting canceled 中 canceled 表被动（会议被取消）。'),
  ('gp-pp-vs-pred-passive', '分词被动 ≠ 谓语被动', 'canceled 是过去分词作非谓语表被动；was canceled 是一般过去时被动谓语。结构上区分：分词前没有 be。');
